mapper.select:
/* Baim05Mapper.selectDailyUserSlotList */ SELECT '' AS chk , A.CMPNY_CD AS cmpnyCd , A.SITE_CD AS siteCd , A.SITE_NM AS siteNm
, A.SLOT_NO AS slotNo , A.SLOT_TYPE AS slotType , A.SLOT_TYPE_NM AS slotTypeNm
, A.FIXED_YN AS fixedYn , A.EXPIRED AS expired , A.USE_YN AS useYn , A.CURR_USER_CD AS currUserId , A.CURR_USER_NM AS currUserNm
, A.MBL_NO_ENC AS mblNo , A.SLOT_STATUS AS slotStatus , A.SLOT_STATUS_NM AS slotStatusNm , A.NODE_CD AS nodeCd , A.NODE_NM AS nodeNm FROM ( SELECT A.CMPNY_CD , A.SITE_CD , FNC_CMM_INFO_SRCH(A.CMPNY_CD, 'SITE', A.SITE_CD, NULL) AS SITE_NM , A.SLOT_NO , A.SLOT_TYPE , FNC_CMM_INFO_SRCH( A.CMPNY_CD , 'SYST_VAL' , A.SLOT_TYPE , 'SYS014' ) AS SLOT_TYPE_NM , A.FIXED_YN , CASE WHEN SLOT_STATUS = '01' THEN '-' ELSE CASE WHEN FIXED_YN = 'Y' THEN '점유 유지 중' ELSE TIMESTAMP(DATE_ADD(CURDATE(), INTERVAL 1 DAY)) END END EXPIRED , A.USE_YN , A.CURR_USER_CD , B.USER_NM AS CURR_USER_NM , B.MBL_NO_ENC , A.SLOT_STATUS , FNC_CMM_INFO_SRCH( A.CMPNY_CD , 'SYST_VAL' , A.SLOT_TYPE , 'SYS015' ) AS SLOT_STATUS_NM , A.NODE_CD , CASE WHEN A.NODE_CD IS NULL OR A.NODE_CD = '' THEN '' ELSE FNC_CMM_INFO_SRCH(A.CMPNY_CD, 'NODE', A.SITE_CD, A.NODE_CD) END AS NODE_NM FROM TB_DAILY_USER_SLOT A LEFT OUTER JOIN TB_DAILY_USER B ON ( A.CMPNY_CD = B.CMPNY_CD AND A.SITE_CD = B.SITE_CD AND A.CURR_USER_CD = B.USER_CD AND B.USE_YN = 'Y' ) WHERE A.CMPNY_CD = #{gvCmpnyCd}
AND A.SITE_CD = #{siteCd}
AND A.SLOT_TYPE = #{slotType}
AND A.SLOT_STATUS = #{slotStatus}
AND A.USE_YN = #{useYn}
) A WHERE 1=1
AND A.CURR_USER_NM LIKE CONCAT('%', #{currUserNm}, '%')
ORDER BY SITE_CD, CAST(A.SLOT_NO AS UNSIGNED)

mapper.update:
	/* Baim05Mapper.saveDailyUserLinkPolicy */
    INSERT INTO TB_DAILY_USER_LINK_POLICY (
    	CMPNY_CD
    	, SITE_CD
    	, USE_YN
    	, DAY_LIMIT_CNT
    	, INSERT_NO
    	, INSERT_DATE
    	, UPDATE_NO
    	, UPDATE_DATE
   	)
   	VALUES(
   		#{gvCmpnyCd}
   		, #{siteCd}
		, IFNULL(#{useYn}, 'Y')
		, #{dayLimitCnt}
		, #{gvUserCd}
		, now()
		, #{gvUserCd}
		, now() 
   	) AS NEW
   	ON DUPLICATE KEY UPDATE
	    USE_YN			= IFNULL(NEW.USE_YN, 'Y')
	    , DAY_LIMIT_CNT = NEW.DAY_LIMIT_CNT
	    , UPDATE_NO   	= NEW.UPDATE_NO
	    , UPDATE_DATE 	= NOW()

