/* Baim05Mapper.selectSiteTopNodeCd */
SELECT NODE_CD
FROM TB_SITE_NODE
WHERE CMPNY_CD = #{cmpnyCd}
  AND SITE_CD = #{siteCd}
  AND PARENT_NODE_CD IS NULL
ORDER BY NODE_CD
LIMIT 1

/* Baim05Mapper.selectOccupiedSlotCntOverLimit */
SELECT COUNT(1)
FROM TB_DAILY_USER_SLOT
WHERE CMPNY_CD = #{cmpnyCd}
  AND SITE_CD = #{siteCd}
  AND CURR_USER_CD IS NOT NULL
  AND CAST(SLOT_NO AS UNSIGNED) >= #{dayLimitCnt}

mapper.update:
	/* Baim05Mapper.saveDailyUserSlot */
	INSERT INTO TB_DAILY_USER_SLOT (
    	CMPNY_CD
    	, SITE_CD
    	, SLOT_NO
    	, SLOT_TYPE
    	, FIXED_YN
    	, USE_YN
    	, CURR_USER_CD
    	, SLOT_STATUS
    	, NODE_CD
    	, INSERT_NO
    	, INSERT_DATE
    	, UPDATE_NO
    	, UPDATE_DATE
   	)
   	VALUES(
   		#{gvCmpnyCd}
   		, #{siteCd}
   		, #{slotNo}
   		, #{slotType}
   		, 'N'
		, #{useYn}
		, ''
		, #{slotStatus}
		, #{nodeCd}		
		, #{gvUserCd}
		, now()
		, #{gvUserCd}
		, now()
   	) AS NEW
   	ON DUPLICATE KEY UPDATE
   		USE_YN		= IFNULL(NEW.USE_YN, 'Y')
   		, SLOT_TYPE     = IF(NEW.USE_YN = 'N', '01', TB_DAILY_USER_SLOT.SLOT_TYPE)
	    , CURR_USER_CD  = IF(NEW.USE_YN = 'N', NULL, TB_DAILY_USER_SLOT.CURR_USER_CD)
	    , SLOT_STATUS   = IF(NEW.USE_YN = 'N', '01', TB_DAILY_USER_SLOT.SLOT_STATUS)

	    , UPDATE_NO   	= NEW.UPDATE_NO
	    , UPDATE_DATE 	= NOW()

