/* Baim05Mapper.selectDailyUserCd */
SELECT CONCAT('D', DATE_FORMAT(NOW(), '%Y%m%d'), FNC_CMM_SEQ_NEXTVAL(#{cmpnyCd}, 'DAILY_USER'))
FROM DUAL

	/* Baim05Mapper.selectDailyUserDuplicateCnt */

	SELECT COUNT(*) 
	FROM (
        SELECT 1
          FROM TB_DAILY_USER
         WHERE CMPNY_CD    = #{cmpnyCd}
           AND MBL_NO_HMAC = #{mblNoHmac}
           AND USE_YN      = 'Y'
         LIMIT 1
    ) T

/* Baim05Mapper.selectLinkPolicyUseYn */
SELECT USE_YN
FROM TB_DAILY_USER_LINK_POLICY
WHERE CMPNY_CD = #{cmpnyCd}
  AND SITE_CD  = #{siteCd}

/* Baim05Mapper.selectTbUserIdDupleCnt */
