mapper.update:
/* Baim05Mapper.reactivateDailyQrUser */
UPDATE TB_DAILY_USER
SET USE_YN                 = 'Y'
	, ACCOUNT_STATUS        = #{accountStatus}
	, SITE_CD               = #{siteCd}
	, USER_NM               = #{userNm}
	, USER_PW               = #{userPw}
	, MBL_NO_ENC            = #{mblNoEnc}
	, MBL_NO_HMAC           = #{mblNoHmac}
	, MBL_NO_LAST4          = #{mblNoLast4}
	, REG_TYPE              = #{regType}
	, WORK_EXPIRE_DATE      = DATE_FORMAT(NOW(), '%Y%m%d')
	, WITHDRAWAL_DATE       = NULL
	, PWD_FAIL_CNT          = 0
	, PWD_LOCK_YN           = 'N'
	, PWD_LOCK_EXPIRE_DTIME = NULL
	, UPDATE_NO             = #{gvUserCd}
	, UPDATE_DATE           = NOW()
WHERE CMPNY_CD = #{gvCmpnyCd}
  AND USER_CD  = #{userCd}

/* Baim05Mapper.reactivateDailyQrUserTbUser */
UPDATE TB_USER
SET USE_YN          = 'Y'
	, ACCOUNT_STATUS = #{accountStatus}
	, SITE_CD        = #{siteCd}
	, USER_NM        = #{userNm}
	, USER_PW        = #{userPw}
	, MBL_NO_ENC     = #{mblNoEnc}
	, MBL_NO_HMAC    = #{mblNoHmac}
	, MBL_NO_LAST4   = #{mblNoLast4}
	, UPDATE_NO      = #{gvUserCd}
	, UPDATE_DATE    = NOW()
WHERE CMPNY_CD        = #{gvCmpnyCd}
  AND USER_CD         = #{userCd}
  AND EMPLOYMENT_TYPE = 'DAILY'

