	, UPDATE_NO = #{gvUserCd}
	, UPDATE_DATE = NOW()
WHERE CMPNY_CD = #{gvCmpnyCd}
  AND SITE_CD = #{siteCd}
  AND SLOT_NO = #{slotNo}

