UPDATE TB_DAILY_USER
SET USE_YN = 'N'
	, ACCOUNT_STATUS = '05'
	, UPDATE_NO = #{gvUserCd}
	, UPDATE_DATE = NOW()
WHERE CMPNY_CD = #{gvCmpnyCd}
  AND USER_CD = #{userCd}

/* Baim05Mapper.deactivateTbUser */
UPDATE TB_USER
SET USE_YN = 'N'
	, ACCOUNT_STATUS = '05'
	, UPDATE_NO = #{gvUserCd}
	, UPDATE_DATE = NOW()
WHERE CMPNY_CD = #{gvCmpnyCd}
  AND USER_CD = #{userCd}
  AND EMPLOYMENT_TYPE = 'DAILY'

/* Baim05Mapper.updateSlotFixed */
UPDATE TB_DAILY_USER_SLOT
SET FIXED_YN = #{fixedYn}
	, UPDATE_NO = #{gvUserCd}
	, UPDATE_DATE = NOW()
WHERE CMPNY_CD = #{gvCmpnyCd}
  AND SITE_CD = #{siteCd}
  AND SLOT_NO = #{slotNo}
  AND SLOT_STATUS = '02'

/* Baim05Mapper.updateSlotType */
UPDATE TB_DAILY_USER_SLOT
SET SLOT_TYPE = #{slotType}
	, UPDATE_NO = #{gvUserCd}
	, UPDATE_DATE = NOW()
WHERE CMPNY_CD = #{cmpnyCd}
  AND SITE_CD = #{siteCd}
  AND SLOT_NO = #{slotNo}
  AND CURR_USER_CD IS NULL
  AND SLOT_STATUS != '02'
  AND USE_YN = 'Y'

