mapper.insert:
/* Baim05Mapper.insertSlotHis */
INSERT INTO TB_DAILY_USER_SLOT_HIS (
	HIS_ID
	, CMPNY_CD
	, SITE_CD
	, SLOT_NO
	, WORK_DATE
	, USER_ID
	, ISSUE_CHANNEL
	, OCCUPY_DTIME
	, RELEASE_USER
	, INSERT_NO
	, INSERT_DATE
)
VALUES (
	#{hisId}
	, #{cmpnyCd}
	, #{siteCd}
	, #{slotNo}
	, #{workDate}
	, #{userId}
	, #{issueChannel}
	, NOW()
	, NULL						
	, #{insertNo}
	, NOW()
)

mapper.update:
/* Baim05Mapper.closeSlotHis */
UPDATE TB_DAILY_USER_SLOT_HIS
SET RELEASE_DTIME = NOW()
	, RELEASE_USER = #{releaseUser}
	, RELEASE_TYPE = #{releaseType}
	, RELEASE_REASON = #{releaseReason}
WHERE CMPNY_CD = #{cmpnyCd}
  AND SITE_CD = #{siteCd}
  AND SLOT_NO = #{slotNo}
  AND RELEASE_DTIME IS NULL

mapper.select:
/* Baim05Mapper.selectDailyUserSlotHisList */ SELECT H.HIS_ID AS hisId , FNC_CMM_INFO_SRCH(H.CMPNY_CD, 'SYST_VAL', H.ISSUE_CHANNEL, 'SYS014') AS issueChannelNm , DATE_FORMAT(H.OCCUPY_DTIME, '%Y-%m-%d %H:%i:%s') AS occupyDtime , DATE_FORMAT(H.RELEASE_DTIME, '%Y-%m-%d %H:%i:%s') AS releaseDtime , CASE WHEN CHAR_LENGTH(D.USER_NM) <= 1 THEN D.USER_NM WHEN CHAR_LENGTH(D.USER_NM) = 2 THEN CONCAT(LEFT(D.USER_NM, 1), '*') ELSE CONCAT(LEFT(D.USER_NM, 2), REPEAT('*', CHAR_LENGTH(D.USER_NM) - 2)) END AS userNmMasked , CASE WHEN D.MBL_NO_LAST4 IS NULL OR D.MBL_NO_LAST4 = '' THEN '-' ELSE CONCAT('010-****-', D.MBL_NO_LAST4) END AS mblNoMasked
, CASE WHEN H.RELEASE_DTIME IS NULL THEN NULL WHEN RU.USER_CD IS NOT NULL THEN CONCAT(RU.USER_NM, '(', RU.USER_ID, ')') ELSE H.RELEASE_USER END AS releaseUser , CASE WHEN H.RELEASE_DTIME IS NULL THEN NULL ELSE FNC_CMM_INFO_SRCH(H.CMPNY_CD, 'SYST_VAL', H.RELEASE_TYPE, 'SYS016') END AS releaseTypeNm , CASE WHEN H.RELEASE_DTIME IS NULL THEN NULL ELSE H.RELEASE_REASON END AS releaseReason FROM TB_DAILY_USER_SLOT_HIS H LEFT OUTER JOIN TB_DAILY_USER D ON ( H.CMPNY_CD = D.CMPNY_CD AND H.USER_ID = D.USER_ID )
LEFT OUTER JOIN TB_USER RU ON ( H.CMPNY_CD = RU.CMPNY_CD AND H.RELEASE_USER = RU.USER_CD ) WHERE H.CMPNY_CD = #{gvCmpnyCd} AND H.SITE_CD = #{siteCd} AND H.SLOT_NO = #{slotNo} AND H.OCCUPY_DTIME >= STR_TO_DATE(#{cutoffYmd}, '%Y%m%d') ORDER BY H.OCCUPY_DTIME DESC

/* Baim05Mapper.countSiteNode */
SELECT COUNT(1)
FROM TB_SITE_NODE
WHERE CMPNY_CD = #{cmpnyCd}
  AND SITE_CD  = #{siteCd}
  AND NODE_CD  = #{nodeCd}

